--- a/rtl/nco_mixer.sv
+++ b/rtl/nco_mixer.sv
@@ -22,19 +22,46 @@
             lut[i] = CW'($rtoi($floor(16383.0 * $sin(6.283185307179586 * i / (2.0**LA)) + 0.5)));
     end

-    wire [LA-1:0] idx = acc[AW-1 -: LA];
-    wire signed [CW-1:0] s = lut[idx];
-    wire signed [CW-1:0] c = lut[idx + LA'(2**(LA-2))];
-    wire signed [XW+CW-1:0] pi = x * c;
-    wire signed [XW+CW-1:0] pq = x * (-s);
+    wire [AW-1:0] acc_next = en ? acc + fw : acc;
+    wire [LA-1:0] next_idx = acc_next[AW-1 -: LA];
+
+    // Prefetch the table values for the phase that will be current next cycle.
+    // This moves the table lookup off the multiply-to-output path without
+    // changing the sample-to-output latency.
+    logic signed [CW-1:0] s_prefetch, c_prefetch;
+    logic signed [CW-1:0] s_pipe, c_pipe;
+    logic signed [XW-1:0] x_pipe;
+    logic valid_pipe;
+
+    wire signed [XW+CW-1:0] pi = x_pipe * c_pipe;
+    wire signed [XW+CW-1:0] pq = x_pipe * (-s_pipe);

     always_ff @(posedge clk) begin
         if (!rst_n) begin
-            acc <= '0; out_valid <= 1'b0; i_out <= '0; q_out <= '0;
+            acc        <= '0;
+            s_prefetch <= lut[0];
+            c_prefetch <= lut[LA'(2**(LA-2))];
+            valid_pipe <= 1'b0;
+            s_pipe     <= '0;
+            c_pipe     <= '0;
+            x_pipe     <= '0;
+            out_valid  <= 1'b0;
+            i_out      <= '0;
+            q_out      <= '0;
         end else begin
-            out_valid <= en;
+            acc        <= acc_next;
+            s_prefetch <= lut[next_idx];
+            c_prefetch <= lut[next_idx + LA'(2**(LA-2))];
+
+            valid_pipe <= en;
             if (en) begin
-                acc   <= acc + fw;
+                s_pipe <= s_prefetch;
+                c_pipe <= c_prefetch;
+                x_pipe <= x;
+            end
+
+            out_valid <= valid_pipe;
+            if (valid_pipe) begin
                 i_out <= XW'(pi >>> 14);
                 q_out <= XW'(pq >>> 14);
             end
